"""Random starting points, shift factors and sample streams, including a
constant stream that exercises the small-persistent-gap behaviour."""


def generate(rng, count):
    builders = (_random_samples, _constant_target, _step_change)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, start, shift, samples, description=""):
    lines = ["%d %d" % (start, shift)]
    lines.extend(str(s) for s in samples)
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _random_samples(rng, index):
    start = rng.randint(-200, 200)
    shift = rng.randint(1, 4)
    samples = [rng.randint(-200, 200) for _ in range(6)]
    return _case("random samples #%d" % index, start, shift, samples)


def _constant_target(rng, index):
    start = rng.randint(0, 500)
    shift = rng.randint(2, 5)
    target = start + rng.randint(-30, 30)
    return _case("a constant target #%d" % index, start, shift,
                 [target] * 6,
                 "The same sample every call -- watch how quickly (or "
                 "whether) the output actually reaches it.")


def _step_change(rng, index):
    start = 0
    shift = rng.randint(1, 3)
    samples = [1000] * 5
    return _case("a step input #%d" % index, start, shift, samples)
